describe('priority', () => {
  it.each(['LOW', 'MEDIUM', 'HIGH'])('adds a task with priority %s', async (p) => {
    const { data } = await gql(`mutation { addTask(title: "x", priority: ${p}) { priority } }`)
    expect(data.addTask.priority).toBe(p)
  })

  it('defaults to MEDIUM when no priority is given', async () => {
    const { data } = await gql('mutation { addTask(title: "x") { priority } }')
    expect(data.addTask.priority).toBe('MEDIUM')
  })

  it('defaults to MEDIUM when priority is null', async () => {
    const { data } = await gql('mutation { addTask(title: "x", priority: null) { priority } }')
    expect(data.addTask.priority).toBe('MEDIUM')
  })

  it('gives seeded tasks MEDIUM', async () => {
    const { data } = await gql('{ tasks { priority } }')
    expect(data.tasks).toEqual([{ priority: 'MEDIUM' }, { priority: 'MEDIUM' }])
  })

  it('rejects an unknown priority and adds nothing', async () => {
    const { data, errors } = await gql('mutation { addTask(title: "x", priority: URGENT) { id } }')
    expect(errors?.length).toBeGreaterThan(0)
    expect(data?.addTask).toBeUndefined()
    const list = await gql('{ tasks { id } }')
    expect(list.data.tasks).toHaveLength(2)
  })
})

