1	export interface Task {
2	  id: string
3	  title: string
4	  done: boolean
5	  createdAt: string
6	}
7	
8	export class TaskStore {
9	  private tasks: Task[] = []
10	  private nextId = 1
11	
12	  constructor(seed: string[] = []) {
13	    seed.forEach((title) => this.add(title))
14	  }
15	
16	  list(): Task[] {
17	    return [...this.tasks]
18	  }
19	
20	  get(id: string): Task | undefined {
21	    return this.tasks.find((t) => t.id === id)
22	  }
23	
24	  add(title: string): Task {
25	    const task: Task = {
26	      id: String(this.nextId++),
27	      title,
28	      done: false,
29	      createdAt: new Date().toISOString(),
30	    }
31	    this.tasks.push(task)
32	    return task
33	  }
34	
35	  toggle(id: string): Task | undefined {
36	    const task = this.get(id)
37	    if (task) task.done = !task.done
38	    return task
39	  }
40	
41	  remove(id: string): boolean {
42	    const before = this.tasks.length
43	    this.tasks = this.tasks.filter((t) => t.id !== id)
44	    return this.tasks.length < before
45	  }
46	}
