import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { AddTaskForm } from './AddTaskForm'
import { TaskItem } from './TaskItem'

describe('AddTaskForm', () => {
  it('submits a trimmed title and clears the box', async () => {
    const onAdd = vi.fn()
    render(<AddTaskForm onAdd={onAdd} />)
    await userEvent.type(screen.getByLabelText('New task'), '  write tests  ')
    await userEvent.click(screen.getByRole('button', { name: 'Add' }))
    expect(onAdd).toHaveBeenCalledWith('write tests', 'MEDIUM')
    expect(screen.getByLabelText('New task')).toHaveValue('')
  })

  it('ignores an empty title', async () => {
    const onAdd = vi.fn()
    render(<AddTaskForm onAdd={onAdd} />)
    await userEvent.click(screen.getByRole('button', { name: 'Add' }))
    expect(onAdd).not.toHaveBeenCalled()
  })

  it('offers low, medium and high with medium selected', () => {
    render(<AddTaskForm onAdd={vi.fn()} />)
    const select = screen.getByLabelText('Priority')
    expect(select).toBeInstanceOf(HTMLSelectElement)
    const options = Array.from((select as HTMLSelectElement).options)
    expect(options.map((o) => o.textContent)).toEqual(['low', 'medium', 'high'])
    expect(options.map((o) => o.value)).toEqual(['LOW', 'MEDIUM', 'HIGH'])
    expect(select).toHaveValue('MEDIUM')
  })

  it('submits the chosen priority and resets to medium', async () => {
    const onAdd = vi.fn()
    render(<AddTaskForm onAdd={onAdd} />)
    await userEvent.selectOptions(screen.getByLabelText('Priority'), 'HIGH')
    await userEvent.type(screen.getByLabelText('New task'), 'ship it')
    await userEvent.click(screen.getByRole('button', { name: 'Add' }))
    expect(onAdd).toHaveBeenCalledWith('ship it', 'HIGH')
    expect(screen.getByLabelText('Priority')).toHaveValue('MEDIUM')
  })
})

describe('TaskItem', () => {
  it('toggles and deletes by id', async () => {
    const onToggle = vi.fn()
    const onDelete = vi.fn()
    render(
      <TaskItem
        task={{ id: '7', title: 'ship', done: false, priority: 'MEDIUM' }}
        onToggle={onToggle}
        onDelete={onDelete}
      />,
    )
    await userEvent.click(screen.getByRole('checkbox'))
    await userEvent.click(screen.getByRole('button', { name: 'Delete ship' }))
    expect(onToggle).toHaveBeenCalledWith('7')
    expect(onDelete).toHaveBeenCalledWith('7')
  })

  it('shows a lowercased priority badge', () => {
    render(
      <TaskItem task={{ id: '7', title: 'ship', done: false, priority: 'LOW' }} onToggle={vi.fn()} onDelete={vi.fn()} />,
    )
    const badge = screen.getByText('low')
    expect(badge).toHaveClass('priority', 'priority-low')
  })
})

